sys_script_fix.script:
(function executeFixScript() {
    var tableName = "change_request";
    var categoryField = "category";
    var categoryLabel = "Cisco Secure Access";
    var categoryValue = "cisco_secure_access"; 
    var policyDesc = "Show Destination fields when Category is Cisco Secure Access";
    var clientScriptName = "Validate Destination Address Field";

    // --- 1) Ensure Category choice exists ---
    var choiceGR = new GlideRecord("sys_choice");
    choiceGR.addQuery("name", tableName);
    choiceGR.addQuery("element", categoryField);
    choiceGR.addQuery("value", categoryValue);
    choiceGR.query();
    if (!choiceGR.next()) {
        choiceGR.initialize();
        choiceGR.name = tableName;
        choiceGR.element = categoryField;
        choiceGR.value = categoryValue;
        choiceGR.label = categoryLabel;
        choiceGR.sequence = 400;
        choiceGR.language = "en";
        choiceGR.insert();
        gs.log("✅ Created new Category choice: " + categoryLabel);
    }

    // --- 2) Create Text Field: u_destination_address ---
    var fieldText = new GlideRecord("sys_dictionary");
    fieldText.addQuery("name", tableName);
    fieldText.addQuery("element", "u_destination_address");
    fieldText.query();
    if (!fieldText.next()) {
        var newField = new GlideRecord("sys_dictionary");
        newField.initialize();
        newField.name = tableName;
        newField.element = "u_destination_address";
        newField.internal_type = "string";
        newField.column_label = "Destination Address";
        newField.max_length = 255;
        newField.mandatory = false;
        newField.insert();
        gs.log("✅ Created text field u_destination_address");
    }

    // --- 3) Create Reference Field: u_destination_list ---
    var fieldRef = new GlideRecord("sys_dictionary");
    fieldRef.addQuery("name", tableName);
    fieldRef.addQuery("element", "u_destination_list");
    fieldRef.query();
    if (!fieldRef.next()) {
        var newRef = new GlideRecord("sys_dictionary");
        newRef.initialize();
        newRef.name = tableName;
        newRef.element = "u_destination_list";
        newRef.internal_type = "reference";
        newRef.reference = "u_cisco_secure_access_destination_list"; 
        newRef.column_label = "Destination List";
        newRef.mandatory = false;
        newRef.insert();
        gs.log("✅ Created reference field u_destination_list");
    }

    // --- 4) Create UI Policy ---
    var uiPolicyGR = new GlideRecord("sys_ui_policy");
    uiPolicyGR.addQuery("table", tableName);
    uiPolicyGR.addQuery("short_description", policyDesc);
    uiPolicyGR.query();
    var policySysId;
    if (!uiPolicyGR.next()) {
        uiPolicyGR.initialize();
        uiPolicyGR.table = tableName;
        uiPolicyGR.short_description = policyDesc;
        uiPolicyGR.order = 100;
        uiPolicyGR.active = true;
        uiPolicyGR.on_load = true;
        uiPolicyGR.on_change = true;
        uiPolicyGR.setValue('conditions', categoryField + "=" + categoryValue + "^EQ");
        policySysId = uiPolicyGR.insert();
        gs.log("✅ Created UI Policy (sys_id = " + policySysId + ")");
    } else {
        policySysId = uiPolicyGR.getUniqueValue();
        gs.log("ℹ️ UI Policy already exists: " + policySysId);
    }

    // --- 5) Create UI Policy Actions ---
    var fieldsToShow = ["u_destination_list", "u_destination_address"];
    fieldsToShow.forEach(function(fieldName) {
        var actionGR = new GlideRecord("sys_ui_policy_action");
        actionGR.addQuery("ui_policy", policySysId);
        actionGR.addQuery("field", fieldName);
        actionGR.query();
        if (!actionGR.next()) {
            actionGR.initialize();
            actionGR.ui_policy = policySysId;
            actionGR.field = fieldName;
            actionGR.mandatory = true;
            actionGR.visible = true;
            actionGR.insert();
            gs.log("✅ Added UI Policy Action for field: " + fieldName);
        }
    });

    // --- 6) Create Client Script for validation ---
    var clientGR = new GlideRecord("sys_script_client");
    clientGR.addQuery("table", tableName);
    clientGR.addQuery("name", clientScriptName);
    clientGR.query();
    if (!clientGR.next()) {
        clientGR.initialize();
        clientGR.name = clientScriptName;
        clientGR.table = tableName;
        clientGR.type = "onChange";
        clientGR.field = "u_destination_address";
        clientGR.ui_type = 0; // 0 = Desktop
        clientGR.active = true;
        clientGR.description = "Validates that Destination Address contains only IPv4, IPv6, URL, or DNS values (multiple allowed).";

        clientGR.script = 
`function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Allow multiple values separated by comma
    var values = newValue.split(/\\s*,\\s*/);

    // Regex patterns
    var ipv4Pattern = /^(25[0-5]|2[0-4]\\d|[0-1]?\\d?\\d)(\\.(25[0-5]|2[0-4]\\d|[0-1]?\\d?\\d)){3}$/;
    var ipv6Pattern = /^(([0-9a-fA-F]{1,4}):){7}([0-9a-fA-F]{1,4})$/;
    var urlPattern  = /^(https?:\\/\\/)?([a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,}(:\\d+)?(\\/.*)?$/;
    var dnsPattern  = /^([a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,}$/;

    var invalidValues = [];

    values.forEach(function(val) {
        if (!(ipv4Pattern.test(val) || ipv6Pattern.test(val) || urlPattern.test(val) || dnsPattern.test(val))) {
            invalidValues.push(val);
        }
    });

    if (invalidValues.length > 0) {
        g_form.showFieldMsg('u_destination_address',
            'Invalid value(s): ' + invalidValues.join(', ') +
            '. Only IPv4, IPv6, URL, or DNS names are allowed.',
            'error');
    } else {
        g_form.hideFieldMsg('u_destination_address');
    }
}`;

        var newClientId = clientGR.insert();
        gs.log("✅ Created Client Script: " + clientScriptName + " (sys_id=" + newClientId + ")");
    } else {
        gs.log("ℹ️ Client Script already exists: " + clientGR.getUniqueValue());
    }

})();
